const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
ctx.imageSmoothingEnabled=false;
const W=960,H=540,GROUND=452;
const ui={overlay:document.getElementById('overlay'),title:document.getElementById('overlayTitle'),copy:document.getElementById('overlayCopy'),button:document.getElementById('startButton'),health:document.getElementById('healthFill'),healthText:document.getElementById('healthText'),kills:document.getElementById('kills'),sideKills:document.getElementById('sideKills'),bossbar:document.getElementById('bossbar'),bossFill:document.getElementById('bossFill'),encounter:document.getElementById('encounter'),toast:document.getElementById('toast')};
let mode='title',last=0,time=0,kills=0,spawnTimer=1.5,shake=0,toastTimer=0,keys={left:false,right:false},particles=[],enemies=[],soul=null;
const player={x:170,y:GROUND-52,w:32,h:52,vx:0,vy:0,health:100,facing:1,onGround:true,attack:0,attackCooldown:0,invuln:0,walk:0};
let boss=null;
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function polygon(points,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill()}
function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function showToast(text){ui.toast.textContent=text;toastTimer=2.1}
function burst(x,y,color,n=12){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-145,145),vy:rand(-210,35),life:rand(.35,.8),max:.8,size:rand(2,5),color})}
function begin(){if(mode!=='title'&&mode!=='dead'&&mode!=='won')return;mode='play';kills=0;enemies=[];particles=[];boss=null;soul=null;spawnTimer=1.5;Object.assign(player,{x:170,y:GROUND-52,vx:0,vy:0,health:100,facing:1,onGround:true,attack:0,attackCooldown:0,invuln:0,walk:0});ui.overlay.classList.add('hidden');ui.bossbar.classList.remove('visible');ui.encounter.textContent='Las sombras ya se agitan…';showToast('LA VIGILIA COMIENZA');updateUI()}
ui.button.addEventListener('click',begin);
function roundRect(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function drawBackground(){
 const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#16141e');g.addColorStop(.58,'#29202a');g.addColorStop(1,'#302326');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // distant ash-lit moon
 ellipse(743,118,92,92,'#c29b7930');ellipse(743,118,70,70,'#c9a98914');
 // distant ruined spires
 for(let i=0;i<9;i++){let x=i*137-30;polygon([[x,355],[x+18,245+((i*37)%85)],[x+29,326],[x+48,278+((i*19)%72)],[x+65,356]],'#1b1922');rect(x+14,320,45,45,'#1a1820')}
 // enormous guardian silhouettes
 // left horned giant
 ellipse(145,268,88,115,'#15141c');polygon([[70,229],[39,91],[119,197],[167,85],[191,232],[201,358],[58,359]],'#15141c');ellipse(148,274,53,79,'#1b1820');polygon([[57,170],[13,99],[81,143],[99,78],[112,161]],'#15141c');polygon([[176,172],[222,83],[203,173],[245,126],[205,232]],'#15141c');
 // right giant head with crown horns
 ellipse(794,237,123,128,'#15141c');polygon([[682,213],[641,67],[733,166],[757,48],[808,177],[884,70],[866,212],[923,120],[885,265],[697,283]],'#15141c');polygon([[716,284],[681,396],[765,335],[788,409],[819,327],[894,391],[859,278]],'#15141c');ellipse(765,241,7,5,'#c15e5740');ellipse(819,241,7,5,'#c15e5740');
 // midground chains hanging
 ctx.strokeStyle='#83706a38';ctx.lineWidth=2;for(let i=0;i<6;i++){let x=74+i*167;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x+Math.sin(time*.4+i)*7,randless(i));ctx.stroke();for(let y=42;y<randless(i);y+=17)ellipse(x,y,3,4,'#88736724')}
 // fog drifts
 for(let i=0;i<5;i++){let x=((i*240+time*11)%1120)-80;ellipse(x,397+(i%2)*18,150,22,'#ac77711a')}
 // horizon
 rect(0,418,W,34,'#1e1b22');polygon([[0,430],[93,416],[171,432],[256,414],[357,433],[457,419],[550,432],[649,412],[752,430],[847,415],[960,429],[960,540],[0,540]],'#17161d');
 // jagged ground strata
 polygon([[0,447],[90,441],[181,449],[276,440],[376,448],[472,441],[576,449],[668,440],[776,449],[868,440],[960,449],[960,540],[0,540]],'#242027');
 rect(0,GROUND,W,H-GROUND,'#17161d');rect(0,GROUND,W,3,'#9b71634a');
 // floor cracks / bones
 for(let i=0;i<15;i++){let x=(i*89+17)%W;polygon([[x,475+i%3*13],[x+13,478+i%3*13],[x+27,474+i%3*13],[x+19,481+i%3*13],[x+9,480+i%3*13]],'#74636324')}
 for(let i=0;i<12;i++){let x=(i*173+50)%W;ellipse(x,GROUND+18+(i%3)*13,3,2,'#d7ad733d')}
 // border vignette
 let v=ctx.createRadialGradient(W/2,H/2,120,W/2,H/2,570);v.addColorStop(.4,'transparent');v.addColorStop(1,'#08080dbb');ctx.fillStyle=v;ctx.fillRect(0,0,W,H);
}
function randless(i){return 220+(i*53)%180}
function drawAngel(){const p=player;ctx.save();ctx.translate(Math.round(p.x+p.w/2),Math.round(p.y+p.h));if(p.facing<0)ctx.scale(-1,1);
 // shadow
 ellipse(0,2,23,5,'#08080a88');
 let bob=p.onGround&&Math.abs(p.vx)>1?Math.sin(p.walk*13)*2:0;
 // wings, gently beating
 let flap=Math.sin(time*5)*3;polygon([[-8,-31],[-30,-39-flap],[-43,-56-flap],[-36,-33],[-26,-24],[-13,-19]],'#e5d7c6');polygon([[-8,-29],[-30,-35-flap],[-23,-24],[-12,-20]],'#b8a99e');
 polygon([[8,-31],[30,-39+flap],[43,-56+flap],[36,-33],[26,-24],[13,-19]],'#e5d7c6');polygon([[8,-29],[30,-35+flap],[23,-24],[12,-20]],'#b8a99e');
 // robe
 polygon([[-10,-34],[10,-34],[14,-5],[19,-1],[0,0],[-19,-1],[-14,-5]],'#d8c6ae');polygon([[-4,-30],[3,-29],[2,-4],[-3,-4]],'#8b7778');rect(-14,-4,12,4,'#b99b80');rect(5,-4,12,4,'#b99b80');
 // head
 ellipse(0,-43+bob,11,12,'#ecdcc7');rect(-10,-49+bob,20,6,'#eee0cc');ellipse(0,-42+bob,10,9,'#e7d5c0');rect(-2,-43+bob,3,2,'#43363b');
 // halo
 ctx.strokeStyle='#e7c786';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,-60+bob,13,4,-.14,0,Math.PI*2);ctx.stroke();
 // sword arm and blade
 let swinging=p.attack>0;ctx.save();if(swinging){let t=1-p.attack/.24;ctx.rotate(-.8+Math.sin(t*Math.PI)*1.5)}
 rect(9,-30+bob,10,5,'#d5bda3');rect(16,-34+bob,4,10,'#b88c69');polygon([[18,-38+bob],[21,-62+bob],[24,-70+bob],[23,-41+bob]],'#dce4e1');rect(17,-42+bob,8,2,'#eac58c');ctx.restore();
 if(swinging){ctx.globalAlpha=.55;ctx.strokeStyle='#f9e3b2';ctx.lineWidth=4;ctx.beginPath();ctx.arc(4,-32+bob,42,-1.15,.72);ctx.stroke();ctx.globalAlpha=1}
 ctx.restore();}

function drawDemon(e){ctx.save();ctx.translate(Math.round(e.x+e.w/2),Math.round(e.y+e.h));if(e.dir<0)ctx.scale(-1,1);ellipse(0,1,e.w*.62,4,'#08070a77');
 const bob=Math.sin(time*8+e.phase)*2;polygon([[-12,-15+bob],[-16,-25+bob],[-12,-20+bob],[-5,-31+bob],[0,-24+bob],[7,-29+bob],[14,-14+bob],[11,-4],[5,0],[-10,0]],'#6d3b3e');polygon([[-12,-18+bob],[-22,-30+bob],[-15,-26+bob],[-11,-32+bob]],'#9a5450');polygon([[4,-24+bob],[12,-34+bob],[10,-25+bob],[16,-29+bob],[13,-18+bob]],'#9a5450');rect(3,-18+bob,4,3,'#f3bf72');rect(10,-18+bob,3,3,'#f3bf72');rect(-8,-4,5,5,'#4e3036');rect(5,-4,5,5,'#4e3036');ctx.restore()}
function drawBoss(){if(!boss)return;const b=boss;ctx.save();ctx.translate(Math.round(b.x+b.w/2),Math.round(b.y+b.h));if(b.dir<0)ctx.scale(-1,1);ellipse(0,3,64,10,'#08070abb');let flash=b.hitFlash>0;
 // massive ragged wings
 polygon([[-27,-64],[-91,-106],[-135,-160],[-123,-92],[-153,-111],[-129,-45],[-68,-24]],flash?'#c67362':'#492a35');polygon([[27,-64],[91,-106],[135,-160],[123,-92],[153,-111],[129,-45],[68,-24]],flash?'#c67362':'#492a35');
 polygon([[-50,-82],[-60,-183],[-38,-162],[-19,-223],[2,-174],[31,-211],[45,-164],[69,-190],[59,-86]],flash?'#b65e54':'#3e2732');
 polygon([[-54,-94],[-45,-149],[-31,-118],[-9,-131],[9,-127],[31,-145],[47,-116],[57,-93],[46,-17],[29,0],[-33,0],[-50,-24]],flash?'#bd6557':'#542e38');
 // ribs
 for(let i=0;i<4;i++){ctx.strokeStyle='#c08b7370';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-30,-67-i*11);ctx.quadraticCurveTo(0,-54-i*11,30,-67-i*11);ctx.stroke()}
 // horns
 polygon([[-40,-164],[-78,-229],[-65,-159],[-49,-133]],'#241c27');polygon([[38,-162],[86,-224],[70,-153],[50,-132]],'#241c27');
 // skull face and eyes
 ellipse(0,-128,29,30,flash?'#e1aa8d':'#a17a70');ellipse(-11,-131,6,9,'#210f1b');ellipse(12,-131,6,9,'#210f1b');ellipse(-11,-130,3,5,'#ffb05f');ellipse(12,-130,3,5,'#ffb05f');polygon([[-9,-109],[0,-99],[8,-109],[0,-106]],'#2a1720');
 // limbs
 rect(-50,-22,21,22,'#382630');rect(26,-22,22,22,'#382630');rect(-62,-6,38,7,'#221b23');rect(24,-6,38,7,'#221b23');
 // flaming crown
 for(let i=0;i<5;i++){let x=-34+i*17,y=-220+Math.sin(time*8+i*2)*6;polygon([[x,y],[x-8,y-18-randless(i)%9],[x+2,y-13],[x+9,y-27-randless(i)%7],[x+9,y]],'#d27757a8')}
 if(b.hitFlash>0){ctx.globalAlpha=.35;ellipse(0,-111,85,100,'#f1a184');ctx.globalAlpha=1}ctx.restore()}
function drawParticles(dt){for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt;p.life-=dt;if(p.life<=0){particles.splice(i,1);continue}ctx.globalAlpha=clamp(p.life/p.max,0,1);rect(p.x,p.y,p.size,p.size,p.color)}ctx.globalAlpha=1}
function updateUI(){const hp=Math.max(0,Math.ceil(player.health));ui.health.style.width=hp+'%';ui.healthText.textContent=hp+'%';ui.kills.textContent=String(kills).padStart(2,'0');ui.sideKills.textContent=String(kills).padStart(2,'0');if(boss){ui.bossbar.classList.add('visible');ui.bossFill.style.width=(Math.max(0,boss.hp/boss.maxHp)*100)+'%'}else ui.bossbar.classList.remove('visible')}
function startBoss(){boss={x:690,y:GROUND-215,w:120,h:215,hp:12,maxHp:12,dir:-1,attackTimer:2,windup:0,hitFlash:0,hitSerial:-1};mode='boss';ui.encounter.textContent='El Devorador ha despertado.';showToast('EL DEVORADOR DESPIERTA');shake=13}
function damagePlayer(amount){if(player.invuln>0||mode==='dead'||mode==='won')return;player.health=Math.max(0,player.health-amount);player.invuln=.85;shake=9;burst(player.x+16,player.y+23,'#d66e67',8);updateUI();if(player.health<=0){mode='dead';ui.title.textContent='La luz se extingue';ui.copy.textContent='El limbo reclama otra alma. Pero incluso aquí, la esperanza puede volver a alzarse.';ui.button.textContent='Volver a intentarlo';ui.overlay.classList.remove('hidden');ui.encounter.textContent='La vigilia terminó.'}}
function hurtEnemy(e){if(e.dead)return;e.hp--;e.hurt=.15;burst(e.x+e.w/2,e.y+e.h/2,'#e58b71',5);if(e.hp<=0){e.dead=true;kills++;burst(e.x+e.w/2,e.y+e.h/2,'#edc78d',15);showToast('ALMA LIBERADA');if(kills>=15&&!boss){startBoss()}updateUI()}}
function hurtBoss(){if(!boss||boss.hitSerial===player.attackSerial)return;boss.hitSerial=player.attackSerial;boss.hp--;boss.hitFlash=.14;shake=5;burst(boss.x+boss.w/2,boss.y+90,'#e7a075',10);if(boss.hp<=0){mode='soul';boss=null;ui.bossbar.classList.remove('visible');soul={x:480,y:GROUND-140,life:0};ui.encounter.textContent='Un alma asciende hacia la luz.';showToast('EL SILENCIO SE ROMPE');updateUI()}}
function attack(){if(mode!=='play'&&mode!=='boss')return;if(player.attackCooldown>0)return;player.attack=.25;player.attackCooldown=.36;player.attackSerial=(player.attackSerial||0)+1;let reach=player.facing>0?player.x+player.w:player.x-58;let right=player.facing>0?reach+61:reach+58;
 for(const e of enemies){if(!e.dead&&Math.abs((e.x+e.w/2)-(player.x+player.w/2))<78&&Math.abs((e.y+e.h/2)-(player.y+player.h/2))<56)hurtEnemy(e)}
 if(boss&&Math.abs((boss.x+boss.w/2)-(player.x+player.w/2))<120&&Math.abs((boss.y+boss.h/2)-(player.y+player.h/2))<180)hurtBoss();}
let attackKey=false;
function onKey(e,down){const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','arrowdown'].includes(k))e.preventDefault();if(k==='a'||k==='arrowleft')keys.left=down;if(k==='d'||k==='arrowright')keys.right=down;if((k===' '||k==='w'||k==='arrowup')&&down&&!e.repeat){if(mode==='title'){begin();return}if(mode==='play'||mode==='boss'){if(player.onGround){player.vy=-570;player.onGround=false;burst(player.x+16,GROUND,'#bca98f',4)}}}if((k==='j'||k==='x')&&down&&!attackKey){attackKey=true;attack()}if(!down&&(k==='j'||k==='x'))attackKey=false;if(k==='enter'&&down&&(mode==='title'||mode==='dead'||mode==='won'))begin()}
window.addEventListener('keydown',e=>onKey(e,true));window.addEventListener('keyup',e=>onKey(e,false));
for(const btn of document.querySelectorAll('.touch-btn')){const key=btn.dataset.key;const set=(v,e)=>{e.preventDefault();btn.classList.toggle('down',v);if(key==='left'||key==='right')keys[key]=v;else if(v&&key==='jump'&&(mode==='play'||mode==='boss')&&player.onGround){player.vy=-570;player.onGround=false;burst(player.x+16,GROUND,'#bca98f',4)}else if(v&&key==='attack')attack()};btn.addEventListener('pointerdown',e=>{btn.setPointerCapture(e.pointerId);set(true,e)});btn.addEventListener('pointerup',e=>set(false,e));btn.addEventListener('pointercancel',e=>set(false,e));btn.addEventListener('lostpointercapture',e=>set(false,e))}

let waves=[];
function update(dt){time+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.textContent=''}if(shake>0)shake=Math.max(0,shake-dt*28);
 const active=mode==='play'||mode==='boss';const p=player;
 if(active){p.attack=Math.max(0,p.attack-dt);p.attackCooldown=Math.max(0,p.attackCooldown-dt);p.invuln=Math.max(0,p.invuln-dt);p.vx=(Number(keys.right)-Number(keys.left))*235;if(p.vx)p.facing=Math.sign(p.vx);if(p.vx)p.walk+=dt; p.x=clamp(p.x+p.vx*dt,32,W-56);p.vy+=1450*dt;p.y+=p.vy*dt;if(p.y+p.h>=GROUND){p.y=GROUND-p.h;p.vy=0;p.onGround=true}else p.onGround=false;
 if(mode==='play'){spawnTimer-=dt;if(spawnTimer<=0&&enemies.filter(e=>!e.dead).length<5){let side=Math.random()<.5?0:1;enemies.push({x:side?W+20:-30,y:GROUND-36,w:32,h:36,hp:1,dir:side?-1:1,phase:rand(0,8),hurt:0,contact:0});spawnTimer=rand(1.05,1.8)}}
 for(let i=enemies.length-1;i>=0;i--){let e=enemies[i];e.hurt=Math.max(0,e.hurt-dt);e.contact=Math.max(0,e.contact-dt);if(e.dead){enemies.splice(i,1);continue}let delta=(p.x+p.w/2)-(e.x+e.w/2);e.dir=Math.sign(delta)||e.dir;e.x+=e.dir*(mode==='boss'?75:72)*dt;if(Math.abs(delta)<36&&Math.abs((p.y+p.h)-(e.y+e.h))<37&&e.contact<=0){damagePlayer(8);e.contact=.85}}
 if(boss){const b=boss;b.dir=Math.sign((p.x+p.w/2)-(b.x+b.w/2))||b.dir;b.hitFlash=Math.max(0,b.hitFlash-dt);b.attackTimer-=dt;if(b.windup>0){b.windup-=dt;if(b.windup<=0){waves.push({x:b.x+(b.dir>0?b.w:-54),y:GROUND-19,dir:b.dir,life:2.2,hit:false});shake=8;b.attackTimer=rand(1.7,2.4)}}else if(b.attackTimer<=0){b.windup=.62;showToast('¡EL DEVORADOR ATACA!')}let target=clamp(p.x-70,430,810);b.x+=clamp(target-b.x,-1,1)*70*dt;if(Math.abs(p.x-b.x)<88&&Math.abs(p.y-b.y)<130&&b.attackTimer<.25)damagePlayer(17)}
 for(let i=waves.length-1;i>=0;i--){let w=waves[i];w.x+=w.dir*285*dt;w.life-=dt;if(!w.hit&&Math.abs(w.x-(p.x+p.w/2))<35&&p.y+p.h>GROUND-35){damagePlayer(14);w.hit=true}if(w.life<=0||w.x<-70||w.x>W+70)waves.splice(i,1)}
 }
 if(mode==='soul'&&soul){soul.life+=dt;soul.y-=48*dt;if(soul.life>3.1){mode='won';ui.title.textContent='Nivel completado';ui.copy.textContent='El alma ha encontrado el cielo. El primer círculo guarda silencio, por ahora.';ui.button.textContent='Volver a jugar';ui.overlay.classList.remove('hidden');ui.encounter.textContent='La luz ha vencido al limbo.';showToast('NIVEL COMPLETADO')}}
 for(const q of particles){q.x+=q.vx*dt;q.y+=q.vy*dt;q.vy+=250*dt;q.life-=dt}
 if(Math.random()<dt*.22&&active)particles.push({x:rand(0,W),y:rand(60,GROUND-20),vx:rand(-10,10),vy:rand(-15,-4),life:2.8,max:2.8,size:rand(1,2),color:'#c6a78555'});
}
function draw(){ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));drawBackground();for(const e of enemies)drawDemon(e);if(boss)drawBoss();for(const w of waves){ellipse(w.x,GROUND-3,24,7,'#e0735977');polygon([[w.x-21,GROUND-4],[w.x,GROUND-24],[w.x+18,GROUND-4]],'#d8785a99')}
 if(mode!=='won'&&mode!=='dead'){if(!(player.invuln>0&&Math.floor(time*18)%2===0))drawAngel()}
 if(soul){let glow=ctx.createRadialGradient(soul.x,soul.y,1,soul.x,soul.y,55);glow.addColorStop(0,'#fff6ce');glow.addColorStop(.15,'#f3d28aab');glow.addColorStop(1,'#e7bb7700');ctx.fillStyle=glow;ctx.fillRect(soul.x-60,soul.y-60,120,120);ellipse(soul.x,soul.y,8,12,'#fff4c9');polygon([[soul.x,soul.y-16],[soul.x+7,soul.y],[soul.x,soul.y+15],[soul.x-7,soul.y]],'#fff9d8');for(let i=0;i<5;i++){let a=time*1.6+i*Math.PI*2/5;ellipse(soul.x+Math.cos(a)*25,soul.y+Math.sin(a)*17,2,2,'#f4d893')}}
 drawParticles(0);ctx.restore();}
function frame(now){let dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}
updateUI();requestAnimationFrame(frame);
</script>
</body>
</html>

